Instance.ref.Members:
var tooltip: GuiTooltip* = null;
var popup: GuiPopup* = null;
var kind: int = -1;
var closed: int = 0;
var commands: int = 0;
var outcome: string = "Ready";

func ShowTransient(value: int): void
{
  kind = value;
  closed = 0;
  outcome = "Pending";
  self.Show();
  if (self.kind == 0)
  {
    tip.DisplayTooltip({x:0 y:40});
    tooltip = cast GuiTooltip* tip.TooltipControl.RelatedControlHost;
  }
  if (self.kind == 1) { popup.ShowPopup(tip, {x:20 y:80} of Point); }
  if (self.kind == 2)
  {
    menu.ShowPopup(tip, true);
    cascade.SubMenuOpening = true;
  }
}

func ReadResult(): string { return outcome; }

Instance.ref.Ctor:
{
        popup = new GuiPopup*(ThemeName::Window);
        popup.ClientSize = {x:180 y:60};
        var label = new GuiLabel*(ThemeName::Label);
        label.Text = "Owned ordinary popup";
        popup.ContainerComposition.AddChild(label.BoundsComposition);
        attach(popup.WindowClosed, func(sender: GuiGraphicsComposition*, arguments: GuiEventArgs*): void { closed = closed + 1; });
        attach(popup.WindowClosing, func(sender: GuiGraphicsComposition*, arguments: GuiRequestEventArgs*): void { arguments.cancel = true; });
      }

Window.ev.WindowReadyToClose-eval:
{
          if (self.kind == 0)
          {
            if (self.tooltip.GetOpening()) { raise "Tooltip still visible"; }
            if (self.tooltip.TemporaryContentControl is not null) { raise "Tooltip content retained"; }
            if (GuiApplication::GetApplication().TooltipOwner is not null) { raise "Tooltip owner retained"; }
          }
          if (self.kind == 1)
          {
            if (self.popup.GetOpening()) { raise "Popup still visible"; }
            if (self.closed != 1) { raise "Popup completion order"; }
          }
          if (self.kind == 2)
          {
            if (menu.GetOpening()) { raise "Menu still visible"; }
            if (cascade.SubMenuOpening) { raise "Submenu state retained"; }
            if (self.closed != 2) { raise "Menu completion order"; }
            if (self.commands != 0) { raise "Dismissal executed command"; }
          }
          self.outcome = "PASS " & (cast string self.kind);
        }

